-- кусок реальной базы Front (MSSQL → PostgreSQL), только области вне ДЗ

drop table if exists bm_securityobjects_info cascade;
drop table if exists bm_securityobjects cascade;
drop table if exists securityaccess cascade;
drop table if exists pricegroup cascade;
drop table if exists recipe cascade;
drop table if exists product cascade;
drop table if exists bm_journalbarnetdocs cascade;
drop table if exists bm_journaltypedocuments cascade;
drop table if exists bm_journaltype cascade;

create table bm_journaltype (
	id bigint not null primary key,
	journalname text
);

create table bm_journaltypedocuments (
	id bigint not null primary key,
	journalid bigint,
	description text
);

create table bm_journalbarnetdocs (
	id bigint not null primary key,
	documenttypeid bigint,
	documentnumber bigint,
	period timestamp,
	dateadd timestamp
);

create table product (
	id bigint not null primary key,
	productid text,
	description text,
	pricegroupid smallint
);

create table recipe (
	id bigint not null primary key,
	documentid bigint,
	recipeid bigint,
	ingredientid bigint,
	portion numeric,
	datecreate timestamp
);

create table pricegroup (
	pricegroupid integer not null primary key,
	description text,
	datestart timestamp
);

create table securityaccess (
	securityaccessid integer,
	description text
);

create table bm_securityobjects (
	id bigint not null primary key,
	parentsystem text,
	securitygroup text,
	objectname text,
	dateadd timestamp
);

create table bm_securityobjects_info (
	id bigint not null primary key,
	parentid bigint,
	keyname text,
	dateadd timestamp
);

alter table bm_journaltypedocuments add foreign key (journalid) references bm_journaltype (id);
alter table bm_journalbarnetdocs add foreign key (documenttypeid) references bm_journaltypedocuments (id);
alter table recipe add foreign key (documentid) references bm_journalbarnetdocs (id);
alter table recipe add foreign key (recipeid) references product (id);
alter table bm_securityobjects_info add foreign key (parentid) references bm_securityobjects (id);
